exercises.solution:
def bilangan_prima(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def prima_sampai(n):
    return [k for k in range(2, n + 1) if bilangan_prima(k)]

