def kuadrat(x):
    return x * x

def kubik(x):
    return x ** 3

f = kuadrat
print(f(4), kuadrat is f)

operasi = {"kuadrat": kuadrat, "kubik": kubik}
for nama, fn in operasi.items():
    print(nama, fn(3))

def terapkan(fn, data):
    return [fn(x) for x in data]

print(terapkan(kuadrat, [1, 2, 3]), terapkan(kubik, [1, 2]))

def buat_pengali(n):
    def kali(x):
        return x * n
    return kali

tiga = buat_pengali(3)
sepuluh = buat_pengali(10)
print(tiga(5), sepuluh(5))

def faktorial(n):
    if n <= 1:
        return 1
    return n * faktorial(n - 1)

print(faktorial(5), faktorial(0))

def ratakan(x):
    if not isinstance(x, list):
        return [x]
    hasil = []
    for e in x:
        hasil += ratakan(e)
    return hasil

print(ratakan([1, [2, [3, 4]], 5]))

exercises.solution:
def buat_penambah(n):
    def tambah(x):
        return x + n
    return tambah

def peringkat(siswa):
    urut = sorted(siswa, key=lambda s: (-s["nilai"], s["nama"]))
    return [s["nama"] for s in urut]

def kedalaman(x):
    if not isinstance(x, list):
        return 0
    if not x:
        return 1
    return 1 + max(kedalaman(e) for e in x)

